+class NoticeUpgradeToProTest extends TestCase {
+
+    /**
+     * @dataProvider configTestData
+     */
+	public function testShouldReturnAsExpected( $config, $expected ) {
+        $was_pro = \BackWPup::is_pro();
+        if ( isset( $config['is_pro'] ) ) {
