7	use Inpsyde\BackWPup\Notice\DismissibleNoticeOption;
8	use Inpsyde\BackWPup\Notice\NoticeView;
9	
10	/**
11	 * Notice to encourage users to upgrade to Pro after a successful backup scheduled job run. This notice is dismissible and will be shown a maximum of 5 times per user, with a limit of one impression per day.
12	 */
13	class NoticeUpgradeToPro extends AbstractNotice {
14	
15	    public const SESSIONS_SHOWN_META_KEY = 'backwpup_upgrade_to_pro_sessions_shown';
16	    public const LAST_SESSION_META_KEY = 'backwpup_upgrade_to_pro_last_session';
17	
18		/**
19		 * The unique ID for this notice.
20		 */
21		public const ID = 'notice_upgrade_to_pro';
22	
23	
24		/**
25		 * Constructor.
26		 *
27		 * @param NoticeView $view The view renderer for the notice.
28		 */
29		public function __construct( NoticeView $view ) {
30			parent::__construct( $view, true );
31		}
32	
33		/**
34		 * Determine if the notice should be displayed.
35		 *
36		 * @return bool
37		 */
38		protected function should_display(): bool {
39			// Never show if the user is in onboarding, is already Pro, or if the parent conditions for display are not met.
40			$onboarding_to_do = get_site_option( 'backwpup_onboarding', false );
41			if ( $onboarding_to_do || BackWPup::is_pro() || ! parent::should_display() ) {
42				return false;
43			}
44	
45			$user_id = get_current_user_id();
46			if ( ! $user_id ) {
47				return false;
48			}
49	
50			// Limit to 5 impressions per user
51			$sessions_shown = (int) get_user_meta( $user_id, self::SESSIONS_SHOWN_META_KEY, true );
52			if ( $sessions_shown >= 5 ) {
53				return false;
54			}
55	
56			// Show once per session (1 session = 1 day)
57			$last_session    = get_user_meta( $user_id, self::LAST_SESSION_META_KEY, true );
58			$current_session = gmdate( 'Y-m-d' ); // 1 session = 1 jour
59			if ( $last_session === $current_session ) {
60				return false;
61			}
62	
63			// Record the impression for the user
64			update_user_meta( $user_id, self::SESSIONS_SHOWN_META_KEY, $sessions_shown + 1 );
65			update_user_meta( $user_id, self::LAST_SESSION_META_KEY, $current_session );
66	
67			return true;
68		}
69	
70		/**
71		 * Render the notice using the view.
72		 *
73		 * @param NoticeMessage $message
74		 */
75		protected function render( NoticeMessage $message ): void {
76			$this->view->success( $message, null );
77		}
78	
79		/**
80		 * Get the dismiss action URL for the notice.
81		 *
82		 * @return string|null
83		 */
84		protected function get_dismiss_action_url(): ?string {
85			if ( ! $this->dismissible ) {
86				return null;
87			}
88	
89			return DismissibleNoticeOption::dismiss_action_url(
90				self::ID,
91				DismissibleNoticeOption::FOR_GOOD_ACTION
92			);
93		}
94	
95		/**
96		 * Build the message for the notice.
97		 *
98		 * @return NoticeMessage
99		 */
100		protected function message(): NoticeMessage {
101			$notice_message             = new NoticeMessage( self::ID );
102			$notice_message->dismissurl = $this->get_dismiss_action_url();
103			return $notice_message;
104		}
105	
106		/**
107		 * Check if the current screen is allowed for this notice.
108		 *
109		 * @return bool
110		 */
111		protected function is_screen_allowed(): bool {
112			$screen = get_current_screen();
113	
114			// Check if the current screen is a BackWPup page.
115			return isset( $screen->id ) && strpos( $screen->id, 'backwpup' ) !== false;
116		}
117	}
