7	
8	/**
9	 * Abstract base class for admin notices.
10	 */
11	abstract class AbstractNotice {
12		/**
13		 * The view renderer for the notice.
14		 *
15		 * @var NoticeView
16		 */
17		protected NoticeView $view;
18	
19		/**
20		 * Whether the notice is dismissible.
21		 *
22		 * @var bool
23		 */
24		protected bool $dismissible;
25	
26		/**
27		 * Unique notice ID.
28		 *
29		 * @var string
30		 */
31		public const ID = 'notice';
32	
33		/**
34		 * Allowed admin page IDs for displaying notices.
35		 *
36		 * @var array
37		 */
38		protected static $main_admin_page_ids = [
39			'toplevel_page_backwpup',
40			'toplevel_page_backwpup-network',
41		];
42	
43		/**
44		 * Initialize the notice, registering dismiss actions if needed.
45		 *
46		 * @return void
47		 */
48		protected function init(): void {
49			if ( ! $this->dismissible ) {
50				return;
51			}
52			// Register dismiss actions for this notice (per-user, not sitewide by default).
53			DismissibleNoticeOption::setup_actions( false, static::ID, 'read' );
54		}
55	
56		/**
57		 * Constructor.
58		 *
59		 * @param NoticeView $view The view renderer for the notice.
60		 * @param bool       $dismissible Whether the notice is dismissible.
61		 */
62		public function __construct( NoticeView $view, bool $dismissible = true ) {
63			$this->view        = $view;
64			$this->dismissible = $dismissible;
65			$this->init();
66		}
67	
68		/**
69		 * Returns whether the current screen should show the notice.
70		 *
71		 * @return bool
72		 */
73		protected function is_screen_allowed(): bool {
74			$screen = get_current_screen();
75			if ( ! $screen instanceof \WP_Screen ) {
76				return false;
77			}
78			return in_array( $screen->id, static::$main_admin_page_ids, true );
79		}
80	
81		/**
82		 * Render the notice if it should be displayed and is on an allowed screen.
83		 *
84		 * @return void
85		 */
86		public function maybe_render(): void {
87			if ( ! $this->is_screen_allowed() ) {
88				return;
89			}
90			if ( ! $this->should_display() ) {
91				return;
92			}
93			$this->render( $this->message() );
94		}
95	
96		/**
97		 * Build the message for the notice.
98		 *
99		 * @return NoticeMessage
100		 */
101		abstract protected function message(): NoticeMessage;
102	
103		/**
104		 * Determine if the notice should be displayed.
105		 *
106		 * @return bool
107		 */
108		protected function should_display(): bool {
109			if ( ! $this->dismissible ) {
110				return true;
111			}
112			$option = new DismissibleNoticeOption( true );
113			return ! $option->is_dismissed( static::ID );
114		}
115	
116		/**
117		 * Render the notice.
118		 *
119		 * @param NoticeMessage $message The message to render.
120		 * @return void
121		 */
122		abstract protected function render( NoticeMessage $message ): void;
123	}
